using Marina.Domain.Catalog; using Marina.Domain.Common;
namespace Marina.Domain.Commerce;
public sealed class CustomerProfile : Entity { public Guid UserId { get; set; } public string DisplayName { get; set; }=""; public string? Phone { get; set; } }
public sealed class Address : Entity { public Guid UserId { get; set; } public string Label { get; set; }=""; public string Recipient { get; set; }=""; public string Phone { get; set; }=""; public string City { get; set; }=""; public string Line1 { get; set; }=""; public string? PostalCode { get; set; } public bool IsDefault { get; set; } }
public sealed class Favorite : Entity { public Guid UserId { get; set; } public Guid ProductId { get; set; } }
public sealed class Cart : Entity { public Guid UserId { get; set; } public ICollection<CartItem> Items { get; set; }=[]; }
public sealed class CartItem : Entity { public Guid CartId { get; set; } public Cart Cart { get; set; }=null!; public Guid VariantId { get; set; } public ProductVariant Variant { get; set; }=null!; public int Quantity { get; set; } }
public sealed class Coupon : Entity { public string Code { get; set; }=""; public DiscountType Type { get; set; } public decimal Value { get; set; } public decimal? MinimumPurchase { get; set; } public decimal? MaximumDiscount { get; set; } public DateTime ValidFromUtc { get; set; } public DateTime ValidToUtc { get; set; } public int? MaxUses { get; set; } public int? MaxUsesPerCustomer { get; set; } public bool IsActive { get; set; }=true; public byte[] RowVersion { get; set; }=[]; }
public sealed class CouponUsage : Entity { public Guid CouponId { get; set; } public Guid UserId { get; set; } public Guid OrderId { get; set; } }
public sealed class Order : Entity { public Guid UserId { get; set; } public Guid AddressId { get; set; } public Guid? CouponId { get; set; } public string PublicNumber { get; set; }=""; public OrderStatus Status { get; set; } public decimal Subtotal { get; set; } public decimal Discount { get; set; } public decimal Shipping { get; set; } public decimal Tax { get; set; } public decimal Total { get; set; } public string IdempotencyKey { get; set; }=""; public string RecipientSnapshot { get; set; }=""; public string AddressSnapshot { get; set; }=""; public byte[] RowVersion { get; set; }=[]; public ICollection<OrderItem> Items { get; set; }=[]; public ICollection<OrderStatusHistory> StatusHistory { get; set; }=[]; }
public sealed class OrderItem : Entity { public Guid OrderId { get; set; } public Guid VariantId { get; set; } public ProductVariant Variant { get; set; }=null!; public string ProductName { get; set; }=""; public string Sku { get; set; }=""; public string? Color { get; set; } public string? Size { get; set; } public decimal UnitPrice { get; set; } public decimal Discount { get; set; } public int Quantity { get; set; } }
public sealed class OrderStatusHistory : Entity { public Guid OrderId { get; set; } public OrderStatus Status { get; set; } public Guid? ActorId { get; set; } public string? Reason { get; set; } }
public sealed class StockMovement : Entity { public Guid VariantId { get; set; } public StockMovementType Type { get; set; } public int OldQuantity { get; set; } public int Delta { get; set; } public int NewQuantity { get; set; } public string Reason { get; set; }=""; public Guid? ReferenceId { get; set; } public Guid? ActorId { get; set; } }
public sealed class Payment : Entity { public Guid OrderId { get; set; } public string Provider { get; set; }=""; public PaymentStatus Status { get; set; } public decimal Amount { get; set; } public string Currency { get; set; }="SAR"; public string IdempotencyKey { get; set; }=""; public ICollection<PaymentTransaction> Transactions { get; set; }=[]; }
public sealed class PaymentTransaction : Entity { public Guid PaymentId { get; set; } public string ProviderReference { get; set; }=""; public string EventType { get; set; }=""; public string PayloadHash { get; set; }=""; public DateTime ProcessedUtc { get; set; }=DateTime.UtcNow; }
public sealed class Notification : Entity { public Guid UserId { get; set; } public NotificationChannel Channel { get; set; } public string Title { get; set; }=""; public string Body { get; set; }=""; public string? DeepLink { get; set; } public DateTime? ReadUtc { get; set; } }
